const detectRegionLanguage = () => {
  try {
    // 1. Check navigator.languages list and navigator.language
    const userLocales = [
      ...(typeof navigator !== 'undefined' && navigator.languages ? navigator.languages : []),
      typeof navigator !== 'undefined' ? navigator.language : null,
      typeof navigator !== 'undefined' ? navigator.userLanguage : null,
    ].filter(Boolean);

    for (const locale of userLocales) {
      const code = locale.toLowerCase().split('-')[0]; // e.g. 'de-DE' -> 'de', 'es-ES' -> 'es'
      if (translations[code]) {
        return code;
      }
    }

    // 2. Check Timezone heuristic for regions
    if (typeof Intl !== 'undefined' && Intl.DateTimeFormat) {
      const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
      if (timeZone.startsWith('Europe/Berlin') || timeZone.startsWith('Europe/Vienna') || timeZone.startsWith('Europe/Zurich')) return 'de';
      if (timeZone.startsWith('Europe/Paris') || timeZone.startsWith('Europe/Brussels')) return 'fr';
      if (timeZone.startsWith('Europe/Madrid')) return 'es';
      if (timeZone.startsWith('Europe/Rome')) return 'it';
      if (timeZone.startsWith('Europe/Amsterdam')) return 'nl';
      if (timeZone.startsWith('Europe/Warsaw')) return 'pl';
      if (timeZone.startsWith('Europe/Dublin')) return 'ga';
      if (timeZone.startsWith('Europe/Moscow') || timeZone.startsWith('Asia/Yekaterinburg')) return 'ru';
      if (timeZone.startsWith('Asia/Tokyo')) return 'ja';
      if (timeZone.startsWith('Asia/Shanghai') || timeZone.startsWith('Asia/Hong_Kong') || timeZone.startsWith('Asia/Taipei')) return 'zh';
      if (timeZone.startsWith('Asia/Seoul')) return 'ko';
      if (timeZone.startsWith('Asia/Riyadh') || timeZone.startsWith('Asia/Dubai') || timeZone.startsWith('Asia/Cairo') || timeZone.startsWith('Asia/Qatar')) return 'ar';
      if (timeZone.startsWith('America/Sao_Paulo') || timeZone.startsWith('Europe/Lisbon')) return 'pt';
      if (timeZone.startsWith('Asia/Kolkata') || timeZone.startsWith('Asia/Calcutta')) {
        // In India, English is standard for cloud tech portfolios with option to switch to Hindi/Marathi
        return 'en';
      }
    }
  } catch (e) {
    // Fallback gracefully
  }
  return 'en';
};

export const LanguageProvider = ({ children }) => {
  const [lang, setLang] = useState(() => {
    const saved = typeof localStorage !== 'undefined' ? localStorage.getItem('portfolio_lang') : null;
    if (saved && translations[saved]) {
      return saved;
    }
    // Auto-select language according to user's region/locale
    const autoLang = detectRegionLanguage();
    return autoLang;
  });

  useEffect(() => {
    localStorage.setItem('portfolio_lang', lang);
  }, [lang]);

  const t = (path, fallbackText = '') => {
    if (!path) return fallbackText || '';
    const keys = path.split('.');
    let current = translations[lang] || translations.en;
    let found = true;
    for (const key of keys) {
      if (current && current[key] !== undefined) {
        current = current[key];
      } else {
        found = false;
        break;
      }
    }
    if (found && current !== undefined && typeof current === 'string') return current;

    // Fallback to English
    let fallback = translations.en;
    let fbFound = true;
    for (const fKey of keys) {
      if (fallback && fallback[fKey] !== undefined) {
        fallback = fallback[fKey];
      } else {
        fbFound = false;
        break;
      }
    }
    if (fbFound && fallback !== undefined && typeof fallback === 'string') return fallback;

    // Return human-readable fallback word from key instead of raw path
    const lastKey = keys[keys.length - 1];
    return fallbackText || lastKey.charAt(0).toUpperCase() + lastKey.slice(1);
  };

  return (
    <LanguageContext.Provider value={{ lang, setLang, t, languagesList }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => useContext(LanguageContext);
